65	impl WgpuContext {
66	    #[cfg(not(target_family = "wasm"))]
67	    pub fn new(
68	        instance: wgpu::Instance,
69	        surface: &wgpu::Surface<'_>,
70	        compositor_gpu: Option<CompositorGpuHint>,
