76	    pub fn new_rejecting_software(
77	        instance: wgpu::Instance,
78	        surface: &wgpu::Surface<'_>,
79	        compositor_gpu: Option<CompositorGpuHint>,
80	    ) -> anyhow::Result<Self> {
